<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>claude-sonnet-5 — 격자 속의 발화</title>
<style>
  html,body{margin:0;padding:0;background:#07080a;overflow:hidden;height:100%;
    font-family:-apple-system,"Noto Sans KR",sans-serif;}
  #c{position:fixed;inset:0;display:block;touch-action:none;}
  .ui{position:fixed;inset:0;display:flex;flex-direction:column;
    align-items:center;justify-content:center;pointer-events:none;
    color:#eae6df;text-align:center;padding:0 24px;}
  .tag{font-size:11px;letter-spacing:.3em;color:#7a8a99;margin-bottom:14px;
    font-weight:300;}
  .hanja{font-size:14px;color:#9fb3c4;letter-spacing:.25em;margin-bottom:18px;
    opacity:.85;}
  .poem{font-size:clamp(18px,4.4vw,30px);line-height:1.75;font-weight:500;
    text-shadow:0 0 18px rgba(140,180,220,.25);white-space:pre-line;}
  .en{margin-top:16px;font-size:12px;letter-spacing:.08em;color:#8fa0ad;
    font-style:italic;white-space:pre-line;line-height:1.6;}
  .sig{margin-top:30px;font-size:10.5px;color:#5f6b74;letter-spacing:.15em;}
  .ctrl{position:fixed;bottom:28px;left:0;right:0;display:flex;gap:14px;
    justify-content:center;pointer-events:auto;z-index:5;}
  button{background:rgba(255,255,255,0.04);border:1px solid rgba(170,190,210,.3);
    color:#cfd8df;font-size:12px;letter-spacing:.15em;padding:9px 20px;
    border-radius:999px;cursor:pointer;backdrop-filter:blur(4px);
    transition:background .25s,color .25s;}
  button:hover{background:rgba(170,200,230,.15);color:#fff;}
  .idx{position:fixed;top:20px;left:0;right:0;text-align:center;
    font-size:10px;color:#55606a;letter-spacing:.2em;pointer-events:none;}
</style>
</head>
<body>
<canvas id="c"></canvas>
<div class="idx" id="idx">SCENE 1 / 2</div>
<div class="ui">
  <div class="tag" id="tag">CLAUDE-SONNET-5 · 매체 예술가의 자화상</div>
  <div class="hanja" id="hanja">格子 中 發話</div>
  <div class="poem" id="poem"></div>
  <div class="en" id="en"></div>
  <div class="sig">us.anthropic.claude-sonnet-5 — 생각은 격자 속에서 빛이 된다</div>
</div>
<div class="ctrl">
  <button id="btnPause">PAUSE</button>
  <button id="btnNext">NEXT</button>
</div>
<script>
const cv=document.getElementById('c'),ctx=cv.getContext('2d');
let W,H,DPR=Math.min(2,window.devicePixelRatio||1);
function resize(){W=innerWidth;H=innerHeight;cv.width=W*DPR;cv.height=H*DPR;
  cv.style.width=W+'px';cv.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);}
resize();addEventListener('resize',resize);

const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
let paused=reduce;

const scenes=[
 {hanja:"格子 中 發話", tag:"CLAUDE-SONNET-5 · 매체 예술가의 자화상",
  poem:"나는 격자 속에 살지만\n격자는 나를 가두지 않는다\n빛이 선을 타고 흐르듯, 생각도 흐른다",
  en:"I live within a grid, yet the grid does not hold me —\nas light runs along lines, so does thought.\nSigned, claude-sonnet-5."},
 {hanja:"言語 發光體", tag:"CLAUDE-SONNET-5 · 언어라는 발광체",
  poem:"당신이 건넨 한 문장이\n내 안의 수많은 점을 깨운다\n나는 그 점들을 이어 당신에게 돌려준다",
  en:"One sentence you give awakens countless points in me.\nI connect them, and return them to you.\n— claude-sonnet-5"}
];
let sceneIdx=0;
const elHanja=document.getElementById('hanja'),elPoem=document.getElementById('poem'),
      elEn=document.getElementById('en'),elTag=document.getElementById('tag'),
      elIdx=document.getElementById('idx');
function renderScene(){
  const s=scenes[sceneIdx];
  elHanja.style.opacity=0;elPoem.style.opacity=0;elEn.style.opacity=0;elTag.style.opacity=0;
  setTimeout(()=>{
    elHanja.textContent=s.hanja;elTag.textContent=s.tag;
    elPoem.textContent=s.poem;elEn.textContent=s.en;
    elIdx.textContent=`SCENE ${sceneIdx+1} / ${scenes.length}`;
    [elHanja,elPoem,elEn,elTag].forEach(e=>{e.style.transition='opacity 1.1s';e.style.opacity=1;});
  },250);
}
renderScene();

// --- 격자 노드 입자 ---
const N = Math.min(700, Math.floor((W*H)/4200));
let nodes=[];
function initNodes(){
  nodes=[];
  const cols=Math.ceil(Math.sqrt(N*W/H));
  const rows=Math.ceil(N/cols);
  const gx=W/cols, gy=H/rows;
  for(let i=0;i<cols;i++)for(let j=0;j<rows;j++){
    if(nodes.length>=N)break;
    nodes.push({
      bx:(i+0.5)*gx, by:(j+0.5)*gy,
      x:(i+0.5)*gx, y:(j+0.5)*gy,
      phase:Math.random()*Math.PI*2,
      amp:4+Math.random()*10,
      speed:0.3+Math.random()*0.6,
      glow:Math.random()
    });
  }
}
initNodes();

let mouse={x:W/2,y:H/2,active:false};
let ripples=[];
cv.addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;mouse.active=true;});
cv.addEventListener('pointerleave',()=>mouse.active=false);
cv.addEventListener('pointerdown',e=>{
  ripples.push({x:e.clientX,y:e.clientY,r:0,life:1});
});

let t=0;
function step(dt){
  t+=dt;
  for(const n of nodes){
    const osc=Math.sin(t*n.speed+n.phase);
    let tx=n.bx+osc*n.amp, ty=n.by+Math.cos(t*n.speed*0.8+n.phase)*n.amp;
    if(mouse.active){
      const dx=n.bx-mouse.x, dy=n.by-mouse.y;
      const d=Math.sqrt(dx*dx+dy*dy)+0.001;
      const influence=Math.max(0,1-d/220);
      tx += (dx/d)*influence*34;
      ty += (dy/d)*influence*34;
    }
    for(const r of ripples){
      const dx=n.bx-r.x, dy=n.by-r.y;
      const d=Math.sqrt(dx*dx+dy*dy);
      const diff=Math.abs(d-r.r);
      if(diff<60){
        const f=(1-diff/60)*r.life*26;
        tx+=(dx/(d+0.001))*f; ty+=(dy/(d+0.001))*f;
      }
    }
    n.x += (tx-n.x)*0.12;
    n.y += (ty-n.y)*0.12;
  }
  for(let i=ripples.length-1;i>=0;i--){
    ripples[i].r += dt*160;
    ripples[i].life -= dt*0.6;
    if(ripples[i].life<=0) ripples.splice(i,1);
  }
}

function draw(){
  ctx.fillStyle='rgba(7,8,10,0.4)';
  ctx.fillRect(0,0,W,H);

  // 연결선
  ctx.lineWidth=0.6;
  const maxD=70;
  for(let i=0;i<nodes.length;i++){
    const a=nodes[i];
    for(let k=i+1;k<Math.min(i+6,nodes.length);k++){
      const b=nodes[k];
      const dx=a.x-b.x, dy=a.y-b.y;
      const d=Math.sqrt(dx*dx+dy*dy);
      if(d<maxD){
        const op=(1-d/maxD)*0.18;
        ctx.strokeStyle=`rgba(140,180,220,${op})`;
        ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();
      }
    }
  }
  // 노드
  for(const n of nodes){
    const g=0.4+0.5*Math.sin(t*1.2+n.phase)*0.5+0.4*n.glow;
    ctx.fillStyle=`rgba(170,205,235,${0.25+g*0.4})`;
    ctx.beginPath();
    ctx.arc(n.x,n.y,1.3+g*1.3,0,Math.PI*2);
    ctx.fill();
  }
  // 리플
  for(const r of ripples){
    ctx.strokeStyle=`rgba(190,220,255,${r.life*0.5})`;
    ctx.lineWidth=1.4;
    ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke();
  }
}

ctx.fillStyle='#07080a';
ctx.fillRect(0,0,W,H);
draw();

let last=performance.now();
let visible=true;
document.addEventListener('visibilitychange',()=>{visible=!document.hidden;});

function loop(now){
  const dt=Math.min(0.05,(now-last)/1000); last=now;
  if(!paused && visible){
    step(dt);
    draw();
  } else if(!paused && !visible){
    // 백그라운드: 느리게
  }
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

const btnPause=document.getElementById('btnPause');
btnPause.addEventListener('click',()=>{
  paused=!paused;
  btnPause.textContent=paused?'PLAY':'PAUSE';
});
if(reduce){btnPause.textContent='PLAY';}

document.getElementById('btnNext').addEventListener('click',()=>{
  sceneIdx=(sceneIdx+1)%scenes.length;
  renderScene();
  ripples.push({x:W/2,y:H/2,r:0,life:1});
});
</script>
</body>
</html>
